begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
alter table public.affiliate_providers add column qa_private_note text default 'Never expose future private columns';
insert into auth.users(id,email) values ('a1111111-1111-4111-8111-111111111111','affiliate-admin@example.test'),('a2222222-2222-4222-8222-222222222222','affiliate-reader@example.test');
insert into public.admin_users(user_id) values ('a1111111-1111-4111-8111-111111111111');
insert into public.affiliate_providers(id,name,official_url,description,media,evidence_urls,last_verified_at,is_enabled,approval_evidence)
values ('qa-affiliate-rls','QA provider','https://example.test/','Rolled-back synthetic provider for RLS checks.',array['photo'],array['https://example.test/evidence'],now(),true,'PRIVATE APPROVAL NOTE');
set local role anon;
select throws_ok($$select * from public.affiliate_providers$$,'42501',null,'Anonymous cannot read private provider rows');
select throws_ok($$update public.affiliate_providers set name='forbidden'$$,'42501',null,'Anonymous cannot modify providers');
select is((select count(*)::int from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),1,'Anonymous gets enabled public projection');
select is((select p->>'affiliate_url' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),null,'Unapproved referral URL absent');
select is((select p ? 'approval_evidence' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),false,'Private approval evidence excluded');
select is((select p ? 'qa_private_note' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),false,'Future columns are not automatically exposed');
select is((select p->>'monetization_ready' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),'false','Unapproved program is not ready');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a2222222-2222-4222-8222-222222222222',true);
select is((select count(*)::int from public.affiliate_providers),0,'Ordinary user cannot read private rows');
select throws_ok($$insert into public.affiliate_providers(id,name,official_url,description,media,evidence_urls,last_verified_at) values ('qa-forbidden','No access','https://example.test/','Denied ordinary-user insert attempt.',array['photo'],array['https://example.test/'],now())$$,'42501',null,'Ordinary user cannot add provider');
with changed as (update public.affiliate_providers set is_enabled=false returning id) select is((select count(*)::int from changed),0,'Ordinary user cannot disable provider');
select set_config('request.jwt.claim.sub','a1111111-1111-4111-8111-111111111111',true);
select is((select count(*)::int from public.affiliate_providers where id='qa-affiliate-rls'),1,'Admin can read private provider');
select throws_ok($$update public.affiliate_providers set affiliate_status='Approved' where id='qa-affiliate-rls'$$,'23514',null,'Approval requires payout and placement confirmation');
select lives_ok($$update public.affiliate_providers set affiliate_status='Approved',program_url='https://example.test/program',payout_confirmed=true,placement_confirmed=true,affiliate_url='https://example.test/?ref=synthetic',verified_affiliate_url='https://example.test/?ref=synthetic',affiliate_url_verified_at=now() where id='qa-affiliate-rls'$$,'Admin may save synthetic approved fixture');
select is((select affiliate_url_verified_at from public.affiliate_providers where id='qa-affiliate-rls'),null,'Changed status and URL reset verification');
update public.affiliate_providers set verified_affiliate_url=affiliate_url,affiliate_url_verified_at=now() where id='qa-affiliate-rls';
select is((select p->>'monetization_ready' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),'true','Exact separately verified URL is ready');
update public.affiliate_providers set affiliate_url_verified_at=now()-interval '31 days' where id='qa-affiliate-rls';
select is((select p->>'monetization_ready' from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),'false','Expired verification disables referral');
select throws_ok($$update public.affiliate_providers set affiliate_url_verified_at=now()+interval '1 day' where id='qa-affiliate-rls'$$,'P0001',null,'Future verification rejected');
update public.affiliate_providers set affiliate_url_verified_at=now(),verified_affiliate_url=affiliate_url where id='qa-affiliate-rls';
update public.affiliate_providers set affiliate_url='https://example.test/?ref=changed' where id='qa-affiliate-rls';
select is((select affiliate_url_verified_at from public.affiliate_providers where id='qa-affiliate-rls'),null,'URL change invalidates exact review');
update public.affiliate_providers set affiliate_url_verified_at=now(),verified_affiliate_url=affiliate_url where id='qa-affiliate-rls';
update public.affiliate_providers set program_url='https://example.test/new-program' where id='qa-affiliate-rls';
select is((select affiliate_url_verified_at from public.affiliate_providers where id='qa-affiliate-rls'),null,'Program change invalidates review');
update public.affiliate_providers set affiliate_url_verified_at=now(),verified_affiliate_url=affiliate_url where id='qa-affiliate-rls';
update public.affiliate_providers set affiliate_status='Rejected' where id='qa-affiliate-rls';
select is((select affiliate_url_verified_at from public.affiliate_providers where id='qa-affiliate-rls'),null,'Rejected status removes verification');
update public.affiliate_providers set is_enabled=false where id='qa-affiliate-rls';
select is((select count(*)::int from public.affiliate_public_providers() p where p->>'id'='qa-affiliate-rls'),0,'Disabled provider absent publicly');
select throws_ok($$update public.affiliate_providers set description='Changed public claims without a new feature review.' where id='qa-affiliate-rls'$$,'P0001',null,'Changed public claims require feature re-verification');
select * from finish();
rollback;
